int unpack_cdf_summary_info(const cdf_stream_t *sst, const cdf_header_t *h,
                            cdf_summary_info_header_t *ssi, cdf_property_info_t **info,
                            size_t *count) {
    size_t prop_count;
    size_t i;

    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    if (sst->offset > sst->size || sst->offset + sizeof(*ssi) > sst->size) {
        return -1;
    }

    ssi->byte_order = cdf_read16(sst, 0);
    ssi->os_version = cdf_read16(sst, 2);
    ssi->os_type = cdf_read16(sst, 4);
    ssi->class = cdf_read32(sst, 8);
    prop_count = cdf_read32(sst, 12);

    *count = prop_count;
    *info = calloc(prop_count, sizeof(cdf_property_info_t));
    if (!*info) {
        return -1;
    }

    for (i = 0; i < prop_count; ++i) {
        size_t offset = 16 + i * sizeof(cdf_property_info_t);
        if (offset + sizeof(**info) > sst->size) {
            free(*info);
            *info = NULL;
            return -1;
        }

        (*info)[i].id = cdf_read16(sst, offset);
        (*info)[i].type = cdf_read16(sst, offset + 2);
        (*info)[i].offset = cdf_read32(sst, offset + 4);
        (*info)[i].size = cdf_read32(sst, offset + 8);
    }

    return 0;
}

int unpack_summary_info(const cdf_stream_t *sst, const cdf_header_t *h, cdf_summary_info_header_t *ssi, cdf_property_info_t **info, size_t *count) {
    size_t prop_count;
    size_t i;
    cdf_property_info_t *prop_info = NULL;

    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    if (h->si_offset + h->si_size > sst->size) {
        return -1;
    }

    memcpy(&ssi->signature, sst->data + h->si_offset, sizeof(ssi->signature));
    memcpy(&ssi->revision, sst->data + h->si_offset + 8, sizeof(ssi->revision));
    memcpy(&ssi->os_version, sst->data + h->si_offset + 10, sizeof(ssi->os_version));
    memcpy(&ssi->os_type, sst->data + h->si_offset + 12, sizeof(ssi->os_type));
    memcpy(&ssi->class, sst->data + h->si_offset + 14, sizeof(ssi->class));
    memcpy(&prop_count, sst->data + h->si_offset + 20, sizeof(prop_count));

    *count = prop_count;
    prop_info = calloc(prop_count, sizeof(cdf_property_info_t));
    if (!prop_info) {
        return -1;
    }

    for (i = 0; i < prop_count; ++i) {
        size_t prop_offset = h->si_offset + 24 + i * sizeof(cdf_property_info_t);
        if (prop_offset + sizeof(cdf_property_info_t) > sst->size) {
            free(prop_info);
            return -1;
        }
        memcpy(&prop_info[i], sst->data + prop_offset, sizeof(cdf_property_info_t));
    }

    *info = prop_info;

    return 0;
}

