int cdf_unpack_summary_info(const cdf_stream_t *sst, const cdf_header_t *h, cdf_summary_info_header_t *ssi, cdf_property_info_t **info, size_t *count) {
    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    // Check stream offsets
    if (sst->size < sizeof(cdf_summary_info_header_t)) {
        return -1;
    }

    // Read summary information from the stream
    size_t bytes_read = 0;
    if (sst_read(sst, &bytes_read, ssi, sizeof(cdf_summary_info_header_t)) != 0) {
        return -1;
    }

    // Validate the count of properties
    if (ssi->property_count > sst->size / sizeof(cdf_property_info_t)) {
        return -1;
    }

    // Allocate memory for the property info array
    *info = (cdf_property_info_t *)malloc(ssi->property_count * sizeof(cdf_property_info_t));
    if (!*info) {
        return -1;
    }

    // Read property info
    size_t i;
    for (i = 0; i < ssi->property_count; ++i) {
        if (sst_read(sst, &bytes_read, &(*info)[i], sizeof(cdf_property_info_t)) != 0) {
            free(*info);
            *info = NULL;
            return -1;
        }
    }

    // Set the count
    *count = ssi->property_count;

    return 0;
}

int unpack_summary_info(const cdf_stream_t *sst, const cdf_header_t *h,
                        cdf_summary_info_header_t *ssi, cdf_property_info_t **info,
                        size_t *count) {
    if (!sst || !h || !ssi || !info || !count) {
        return -1;
    }

    if (sst->size < h->summary_info_offset || sst->size < h->summary_info_offset + h->summary_info_size) {
        return -1;
    }

    if (fseek(sst->file, h->summary_info_offset, SEEK_SET) != 0) {
        return -1;
    }

    if (fread(ssi, h->summary_info_size, 1, sst->file) != 1) {
        return -1;
    }

    *count = ssi->property_count;
    *info = (cdf_property_info_t *)malloc((*count) * sizeof(cdf_property_info_t));
    if (!*info) {
        return -1;
    }

    for (size_t i = 0; i < *count; ++i) {
        if (fread(&(*info)[i], sizeof(cdf_property_info_t), 1, sst->file) != 1) {
            free(*info);
            *info = NULL;
            *count = 0;
            return -1;
        }
    }

    return 0;
}
